mapper.select:
SELECT * FROM ( SELECT ROWNUM AS RNUM, A.* FROM ( SELECT c.concert_id, c.title, c.artist, c.venue, c.status, c.thumbnail, COUNT(*) OVER() AS TOTAL_COUNT FROM concerts c
AND c.status = #{status}
AND LOWER(c.title) LIKE '%' || LOWER(#{keyword}) || '%'
AND LOWER(c.artist) LIKE '%' || LOWER(#{keyword}) || '%'
AND ( LOWER(c.title) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(c.artist) LIKE '%' || LOWER(#{keyword}) || '%' )
ORDER BY c.concert_id DESC ) A WHERE ROWNUM <= #{END} ) WHERE RNUM >= #{START}

mapper.insert:
INSERT INTO concerts ( title, artist, venue, description, thumbnail, status ) VALUES ( #{title}, #{artist}, #{venue}, #{description, jdbcType=CLOB}, #{thumbnail},
#{status} 'UPCOMING'
)

mapper.update:
UPDATE concerts
SET    status = 'CLOSED'
WHERE  concert_id = #{concertId}

mapper.delete:
DELETE FROM bookings
WHERE  schedule_id IN (
	SELECT schedule_id
	FROM   concert_schedules
	WHERE  concert_id = #{concertId}
)

DELETE FROM seats
WHERE  schedule_id IN (
	SELECT schedule_id
	FROM   concert_schedules
	WHERE  concert_id = #{concertId}
)

mapper.select:
SELECT * FROM ( SELECT ROWNUM AS RNUM, A.* FROM ( SELECT m.member_id, m.email, m.name, m.phone, m.birth_date, m.role, COUNT(*) OVER() AS TOTAL_COUNT FROM members m
AND m.role = #{role}
AND LOWER(m.email) LIKE '%' || LOWER(#{keyword}) || '%'
AND LOWER(m.name) LIKE '%' || LOWER(#{keyword}) || '%'
AND ( LOWER(m.email) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(m.name) LIKE '%' || LOWER(#{keyword}) || '%' )
ORDER BY m.member_id DESC ) A WHERE ROWNUM <= #{END} ) WHERE RNUM >= #{START}
